"""Campaign construction helpers for the development tests."""
import base64, io, json, sys
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/deps')
import zstandard as zstd
from common import COLUMNS

HEADER = ','.join(COLUMNS)

def row(**kw):
    base = {'type': 'icmp', 'id': 'x', 'revision': '0', 'published': '0', 'op': 'put',
            'lease': '', 'event': '', 'probe': '', 'target': '', 'responder': '',
            'result': '', 'service': '', 'attempt': '', 'payload': ''}
    base.update({k: ('' if v is None else str(v)) for k, v in kw.items()})
    return [base[c] for c in COLUMNS]

def capture(rows, encoding='csv', splits=1, header=True, raw=None, terminator='\n'):
    if raw is None:
        text = (HEADER + terminator if header else '')
        for r in rows:
            text += ','.join(r) + terminator
        data = text.encode()
    else:
        data = raw
    if encoding == 'zstd':
        data = zstd.ZstdCompressor().compress(data)
    size = max(1, -(-len(data) // splits))
    chunks = [base64.b64encode(data[i:i + size]).decode() for i in range(0, len(data), size)] or ['']
    return {'encoding': encoding, 'chunks': chunks}

def campaign(**kw):
    job = {'version': 3, 'seed': kw.pop('seed', 'demo'), 'leases': [], 'services': [],
           'queries': [10], 'captures': [], 'requests': [], 'offers': [],
           'request_quotas': [{'id': 'all', 'parent': None, 'capacity': 4096}],
           'offer_quotas': [{'id': 'all', 'parent': None, 'capacity': 4096}]}
    job.update(kw)
    return job

def lease(lid='home', prefix='2001:db8:1:1200::/56', start=0, end=100, subnets=(0,), low_count=2):
    return {'id': lid, 'prefix': prefix, 'start': start, 'end': end,
            'subnets': list(subnets), 'low_count': low_count}

def service(sid='web', kind='tcp'):
    return {'id': sid, 'kind': kind}

def quota(nid, parent=None, capacity=4096):
    return {'id': nid, 'parent': parent, 'capacity': capacity}

def run(job, expect_error=None):
    """Run the campaign in-process (same code path as campaign.main)."""
    import importlib
    import campaign as mod
    importlib.reload(mod)
    if expect_error is not None:
        raw = json.dumps(job).encode() if not isinstance(job, bytes) else job
        try:
            mod.audit(mod.parse_json(raw))
        except mod.CaptureError:
            assert expect_error == 'capture', 'expected %s got capture' % expect_error
            return {'error': 'capture'}
        except mod.Invalid as exc:
            assert expect_error == 'invalid', 'expected %s got invalid: %s' % (expect_error, exc)
            return {'error': 'invalid'}
        raise AssertionError('expected error %s, got a result' % expect_error)
    return mod.audit(job)

def manifest_of(result, lease=None):
    return [m for m in result['manifest'] if lease is None or m['lease'] == lease]

def snapshot(result, index=0):
    return result['snapshots'][index]

def lease_report(result, lid, index=0):
    for entry in snapshot(result, index)['leases']:
        if entry['lease'] == lid:
            return entry
    raise KeyError(lid)

def service_report(result, lid, sid, index=0):
    for entry in lease_report(result, lid, index)['services']:
        if entry['id'] == sid:
            return entry
    raise KeyError(sid)
PYEOF
